CREATE TABLE "mesh_signing_keys" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "key_id" character varying NOT NULL, "account_subject" character varying NOT NULL, "public_key" character varying NOT NULL, "seed" character varying NOT NULL, "active" boolean NOT NULL DEFAULT false, "secret_binding" character varying NOT NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "mesh_signing_keys_key_id_key" ON "mesh_signing_keys" ("key_id");
CREATE INDEX "meshsigningkey_account_subject" ON "mesh_signing_keys" ("account_subject");
